const account = $input.first().json;

const storyTypes = Array.isArray(account.storyTypes) ? account.storyTypes : JSON.parse(account.storyTypes || '[]');
const storyType = storyTypes[Math.floor(Math.random() * storyTypes.length)] || 'motivational';

// Background videos + their real durations (in seconds) — ffprobed once, stored here.
// If you add a new file to /home/dragon/videos, add its duration here too.
const VIDEO_DURATIONS = {
  'minecraft_vertical.mp4': 1852,
  'subway_surfers_vertical.mp4': 3763
};
const videos = Object.keys(VIDEO_DURATIONS);
const bgVideo = videos[Math.floor(Math.random() * videos.length)];
const bgVideoDuration = VIDEO_DURATIONS[bgVideo];

const voiceMap = {
  male: 'en-US-ChristopherNeural',
  female: 'en-US-JennyNeural'
};
const voice = voiceMap[(account.voiceType || 'male').toLowerCase()] || 'en-US-ChristopherNeural';

const jobId = `${account.id}_${Date.now()}`;

return [{
  json: { ...account, storyType, bgVideo, bgVideoDuration, voice, jobId }
}];

