={{ JSON.stringify({
  video_file: $('Set Merged Audio').first().json.bgVideo,
  audio_url: $('Set Merged Audio').first().json.ttsUrl,
  start: (() => {
    const audioDur = Math.ceil(parseFloat($input.first().json.duration || 60));
    const bgDur = $('Set Merged Audio').first().json.bgVideoDuration || 1800;
    const maxStart = Math.max(0, bgDur - audioDur - 5);
    const startSec = Math.floor(Math.random() * maxStart);
    const h = Math.floor(startSec / 3600);
    const m = Math.floor((startSec % 3600) / 60);
    const s = startSec % 60;
    return String(h).padStart(2,'0') + ':' + String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0') + '.000';
  })(),
  duration: $input.first().json.duration || 60,
  job_id: $('Set Merged Audio').first().json.jobId || ''
}) }}

