const raw = $input.first().json.text || '';
if (!raw) throw new Error('LLM returned empty script');

const ctx = $('Prepare Job').first().json;

// Split by paragraph breaks, clean each part
const parts = raw
  .split(/\n\n+/)
  .map(p => p.replace(/\n/g, ' ').replace(/\\n/g, ' ').replace(/  +/g, ' ').trim())
  .filter(p => p.length > 0);

if (parts.length === 0) throw new Error('Script split produced no parts');

// Full script for caption use
const fullScript = parts.join(' ');

// Return one item per part, each carries the full script too
return parts.map((partText, partIndex) => ({
  json: { ...ctx, partText, partIndex, totalParts: parts.length, fullScript }
}));

const info = $input.first().json;
const ctx = $('Prepare Post URL').first().json;
const allowed = info?.privacy_level_options || info?.data?.privacy_level_options || [];
const preferred = ['PUBLIC_TO_EVERYONE','FOLLOWER_OF_CREATOR','MUTUAL_FOLLOW_FRIENDS','SELF_ONLY'];
const privacyLevel = preferred.find(p => allowed.includes(p)) || 'PUBLIC_TO_EVERYONE';
return [{ json: { ...ctx, privacyLevel } }];

// Gather all TTS part URLs from all items
const items = $input.all();
const audioUrls = items.map(item => ({ audio_url: item.json.url }));

// Carry context from first item
const ctx = items[0].json;
// Get context fields we need (from Prepare Job via first TTS item)
const jobCtx = $('Prepare Job').first().json;

return [{ json: { ...jobCtx, audioUrls } }];

const mergedUrl = $input.first().json.url;
const ctx = $('Collect TTS URLs').first().json;
return [{ json: { ...ctx, ttsUrl: mergedUrl } }];

